import * as React from "react";
import { cn } from "cn";

import styles from "./runtime.module.css";

export type SpinnerSize = "inline" | "base" | "page";
const grids = {
  base: [
    "..####....####..",
    ".######..######.",
    "##....####....##",
    "##.....##.....##",
    "##.....##.....##",
    "##....####....##",
    ".######..######.",
    "..####....####.."
  ],
  page: [
    ".....######..........######.....",
    "...##########......##########...",
    "..############....############..",
    ".##############..##############.",
    ".####......##########......####.",
    "####........########........####",
    "####.........######.........####",
    "####..........####..........####",
    "####..........####..........####",
    "####.........######.........####",
    "####........########........####",
    ".####......##########......####.",
    ".##############..##############.",
    "..############....############..",
    "...##########......##########...",
    ".....######..........######....."
  ]
};

type SpinnerProps = Omit<React.ComponentPropsWithoutRef<"svg">, "children"> & {
  size?: SpinnerSize;
  label?: string;
  description?: string;
  delay?: number;
};

const useAfterDelay = (delay: number) => {
  const [shown, setShown] = React.useState(delay <= 0);
  React.useEffect(() => {
    if (delay <= 0) {
      setShown(true);
      return;
    }
    setShown(false);
    const timer = window.setTimeout(() => setShown(true), delay);
    return () => window.clearTimeout(timer);
  }, [delay]);
  return shown;
};

export const Spinner = React.forwardRef<SVGSVGElement, SpinnerProps>(
  ({ size = "inline", label, description, delay = 0, className, ...props }, ref) => {
    const shown = useAfterDelay(delay);
    const grid = grids[size === "page" ? "page" : "base"];
    const pitch = size === "page" ? 5 : size === "base" ? 3 : 1;
    const dot = size === "page" ? 4 : size === "base" ? 2 : 1;
    const width = (grid[0].length - 1) * pitch + dot;
    const height = (grid.length - 1) * pitch + dot;
    if (!shown) return null;
    const mark = (
      <svg
        ref={ref}
        data-slot="spinner"
        data-size={size}
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        className={cn(styles.spinner, styles[size], label === undefined && className)}
        aria-hidden
        focusable="false"
        {...(label === undefined ? props : {})}
      >
        {grid.flatMap((row, y) =>
          [...row].flatMap((pixel, x) =>
            pixel === "#"
              ? [
                  <rect
                    key={`${x}-${y}`}
                    x={x * pitch}
                    y={y * pitch}
                    width={dot}
                    height={dot}
                    data-cross={
                      Math.abs(x + y + 1 - (grid[0].length + grid.length) / 2) <=
                        (size === "page" ? 2 : 1) &&
                      Math.abs(x - y - (grid[0].length - grid.length) / 2) <=
                        (size === "page" ? 2 : 1)
                        ? ""
                        : undefined
                    }
                    style={{
                      animationDelay: (() => {
                        const columns = grid[0].length;
                        const centerY = grid.length / 2;
                        const right = x + 0.5 > columns / 2;
                        const angle =
                          (Math.atan2(
                            y + 0.5 - centerY,
                            x + 0.5 - columns * (right ? 0.7276 : 0.2724)
                          ) *
                            180) /
                          Math.PI;
                        const phase = right
                          ? ((((angle - 180) % 360) + 360) % 360) / 720
                          : 0.5 + (((-angle % 360) + 360) % 360) / 720;
                        const steps = size === "page" ? 40 : 24;
                        const snapped = Math.floor(phase * steps) / steps;
                        return size === "page"
                          ? `${Math.hypot(x - columns / 2, y - centerY) * 0.02}s, ${0.95 + snapped * 2.4}s`
                          : `${-(1 - snapped) * 1.6}s`;
                      })()
                    }}
                  />
                ]
              : []
          )
        )}
      </svg>
    );
    if (label === undefined) return mark;
    return (
      <div
        data-slot="spinner-status"
        data-size={size}
        role="status"
        aria-live="polite"
        className={cn(
          styles.status,
          size === "inline" && styles.statusInline,
          size === "page" && styles.statusPage,
          className
        )}
        {...(props as React.ComponentPropsWithoutRef<"div">)}
      >
        {mark}
        <span className={styles.statusLabel}>{label}</span>
        {description && size === "page" && (
          <span className={styles.statusDescription}>{description}</span>
        )}
      </div>
    );
  }
);
Spinner.displayName = "Spinner";

.spinner {
  display: inline-block;
  flex-shrink: 0;
  overflow: visible;
}
.spinner rect {
  fill: currentColor;
}
.base,
.page {
  color: var(--v4-mark, var(--v4-accent-fg));
}
.inline rect,
.base rect {
  /* v4-check-ignore motion-literal -- spinner choreography, one owner */
  animation: pixelTrail 1.6s linear infinite;
}
.page rect {
  transform-box: fill-box;
  transform-origin: center;
  animation:
    /* v4-check-ignore motion-literal -- spinner choreography, one owner */
    pixelAssemble 0.95s ease-out backwards,
    /* v4-check-ignore motion-literal -- same spinner */ pixelTrail 2.4s linear infinite;
}
.inline rect[data-cross],
.base rect[data-cross] {
  animation-name: pixelCross;
}
.page rect[data-cross] {
  animation-name: pixelAssemble, pixelCross;
}
.status {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--v4-space-12);
  text-align: center;
}
.statusInline {
  display: inline-flex;
  flex-direction: row;
  gap: var(--v4-space-8);
  text-align: start;
  vertical-align: middle;
}
.statusPage {
  width: 100%;
  min-height: 100%;
  flex: 1 1 auto;
  padding: var(--v4-space-40) var(--v4-space-20);
}
.statusLabel {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted, var(--muted-foreground));
}
.statusInline .statusLabel {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: inherit;
}
.statusPage .statusLabel {
  font-family: var(--v4-type-title-sm-font-family);
  font-size: var(--v4-type-title-sm-font-size);
  line-height: var(--v4-type-title-sm-line-height);
  font-weight: var(--v4-type-title-sm-font-weight);
  letter-spacing: var(--v4-type-title-sm-letter-spacing);
  margin-top: var(--v4-space-16);
}
.statusDescription {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  max-width: 40ch;
  color: var(--v4-muted, var(--muted-foreground));
}
.busy {
  position: relative;
  overflow: hidden;
}
.busy::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-radial-gradient(circle at 1px 1px, currentColor 0 1px, transparent 1px 3px);
  opacity: 0.16;
  /* v4-check-ignore motion-literal -- spinner choreography, one owner */
  animation: busyBand 1.2s steps(28) infinite;
}
@keyframes pixelTrail {
  0%,
  100% {
    opacity: 0.3;
  }
  25% {
    opacity: 1;
  }
  50% {
    opacity: 0.65;
  }
  75% {
    opacity: 0.4;
  }
}
@keyframes pixelCross {
  0%,
  50%,
  100% {
    opacity: 0.65;
  }
  9%,
  59% {
    opacity: 0.56;
  }
  25%,
  75% {
    opacity: 1;
  }
}
@keyframes pixelAssemble {
  from {
    opacity: 0;
    transform: scale(0.3);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes busyBand {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(100%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .spinner rect,
  .spinner rect[data-cross],
  .busy::after {
    animation: none;
    opacity: 1;
    transform: none;
  }
  .busy::after {
    opacity: 0.1;
  }
}
